/* Reveal → hold → resolve. Rules are mirrored in L.motionRules for Web Animations. */
:root{--motion-reveal:180ms;--motion-hold:80ms;--motion-resolve:220ms;--motion-press:100ms;--ease-focus:cubic-bezier(.2,.75,.3,1)}
/* Supersede legacy local entrance/counter effects. All final facts exist at first paint. */
html.lumo-motion-ready #view .screen,
html.lumo-motion-ready #view .pay-tab-panel,
html.lumo-motion-ready #view .scene-art svg,
html.lumo-motion-ready #view .focus-art .scene-art svg,
html.lumo-motion-ready #view .money-art,
html.lumo-motion-ready #view .money-art>circle,
html.lumo-motion-ready #view .welcome-illustration,
html.lumo-motion-ready #view .welcome-illustration svg,
html.lumo-motion-ready #view .focus-balance-track>span,
html.lumo-motion-ready #view .focus-category-track>span{animation:none}
button,.quick-actions button>span{transition:transform var(--motion-press) var(--ease-focus),background-color var(--motion-reveal) ease,border-color var(--motion-reveal) ease,box-shadow var(--motion-reveal) ease}
button:not(:disabled):active{transform:scale(.985)}
.row:not(:disabled):active{background:var(--soft,#edf0e8)}
.quick-actions button:not(:disabled):active{transform:none}
.quick-actions button:not(:disabled):active>span{transform:scale(.96)}
.nav-item svg{transition:transform var(--motion-press) var(--ease-focus),stroke-width var(--motion-reveal) ease}
.nav-item:not(:disabled):active svg{transform:scale(.96)}
.chip{transition:background-color var(--motion-reveal) ease,color var(--motion-reveal) ease,transform var(--motion-press) ease}
.toggle:after{transition:left var(--motion-reveal) var(--ease-focus)}
[data-insight],[data-projection],.success-mark,.result-mark{transform-origin:center}
.balance-main,[data-pause-balance]{font-variant-numeric:tabular-nums}
.success-mark svg path,.result-mark svg path{stroke-linecap:round;stroke-linejoin:round}
.pause-scene{isolation:isolate}
.pause-wallet,.pause-recipient{transform-origin:center}
.pause-payment-token{pointer-events:none;z-index:2;opacity:0}
.pause-route-line{transition:opacity var(--motion-reveal) ease}
.pause-ring-progress{transform-origin:center;stroke-linecap:round}
.pause-room-bar{overflow:hidden}
.pause-is-complete .pause-payment-token{opacity:0}
/* The wordmark’s rounded counter becomes a quiet, functional focus edge. */
#view.lumo-balances-revealed .home-plan-summary{outline:1px solid var(--line,#d4dacd);outline-offset:3px;transition:outline-color var(--motion-resolve) ease}
@media(hover:hover){
 .quick-actions button:hover>span{transform:translateY(-1px)}
}
.lumo-motion-paused #view *,
.lumo-motion-paused #view *::before,
.lumo-motion-paused #view *::after{animation:none!important;transition:none!important}
@media(prefers-reduced-motion:reduce){
 *,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}
 button:not(:disabled):active,.quick-actions button:not(:disabled):active>span,.nav-item:not(:disabled):active svg,.quick-actions button:hover>span{transform:none}
 .pause-payment-token{display:none}
}

