/* Inherited role measurements. Original Lumo Sans faces load in clarity-type.css; the wordmark is an SVG. */
:root {
  --font-ui: 'Lumo Sans', Arial, sans-serif;
  --weight-regular: 400;
  --weight-medium: 500;
  --weight-semibold: 600;
  --weight-bold: 700;
  --type-title: clamp(2rem, 8.4vw, 2.375rem);
  --type-consequence: clamp(1.5rem, 6.6vw, 1.875rem);
  --type-amount: clamp(2.5rem, 11.4vw, 3rem);
  --type-body: 1rem;
  --type-support: .9375rem;
  --type-meta: .8125rem;
}

html { font-synthesis: none; }
body { font-family: var(--font-ui); font-size: var(--type-body); font-weight: 400; line-height: 1.5; }
button, input, select, textarea { font-family: inherit; }
b, strong { font-weight: 600; }
h1, h2, h3 { font-weight: 700; }

/* Titles orient; conclusions state the change; amounts make it concrete. */
.screen .page-heading h1,
.screen .hero h1,
.screen .focus-pay-heading h1,
.screen .destination-heading h1,
.screen .focus-story-heading h1 {
  font-size: var(--type-title);
  font-weight: 700;
  line-height: 1.12;
  letter-spacing: -.045em;
}
.screen .focus-pause-insight h1,
.screen-chat .chat-reply .lead,
.lumo-conclusion {
  font-size: var(--type-consequence);
  font-weight: 600;
  line-height: 1.22;
  letter-spacing: -.035em;
}
.screen-home .home-plan-summary strong,
.screen .focus-payment-title h1,
.screen .plan-room>strong,
.screen .focus-story-total>strong,
