.screen-pause .pause-decision-consequence .pause-goal-impact{font-weight:600;margin-top:7px}
.screen-pause .pause-decision-consequence .pause-total-impact,.screen-pause .pause-decision-consequence .pause-existing-gap{font-size:12px;color:var(--green-ink);line-height:1.45}
.screen-pause .pause-decisions .pause-equal-choice{font-size:14px;min-height:54px;border:var(--stroke) solid var(--ink);background:var(--paper);font-weight:700;border-radius:var(--curve-control);padding:12px 8px;line-height:1.35}
.screen-pause .focus-pause-compact .focus-choice{font-size:13px;margin-top:10px;font-weight:500}
.screen-pause .pause-actions .pause-link-cost,.screen-pause .focus-pause-exits .text-btn{min-height:44px;font-size:13px;font-weight:600}
.screen-pause .focus-pause-compact .focus-footnote{font-size:12px;margin-top:5px;color:var(--green-ink)}
.screen-paymentResult .hero{gap:10px!important;margin-bottom:18px}
.screen-paymentResult .hero h1{font-size:29px;line-height:1.16;letter-spacing:-.8px;font-weight:600}
.screen-paymentResult .result-mark{height:58px;width:58px;border-radius:50%;margin:10px 0 8px;background:var(--soft);border:var(--stroke) solid var(--control-line)}
.screen-paymentResult [data-payment-state=confirmed] .result-mark{background:var(--green-soft);border-color:var(--green-ink)}
.screen-paymentResult [data-payment-state=failed] .result-mark,.screen-paymentResult [data-payment-state=delivery-failed] .result-mark{background:var(--shortfall-soft);border-color:var(--red)}
.screen-paymentResult .receipt{padding:18px}
/* The same conclusion style leads the conversation. */
.screen-chat .chat-has-conversation .page-heading h1{font-size:26px;font-weight:600;letter-spacing:-.7px}
.screen-chat .chat-bubble.user{font-size:14px;background:var(--soft);border-radius:20px 20px 8px 20px}
.screen-chat .chat-reply{border-radius:var(--curve-bubble);padding:18px 18px 16px;background:var(--white);border-left:3px solid var(--green)}
