.screen-chat .chat-reply .impact-secondary{font-size:14px;line-height:1.5;color:var(--muted)}
.screen-chat .chat-calculation{font-size:13px;border-color:var(--line)}
.screen-chat .chat-calculation>summary,.screen-chat .chat-context>summary,.screen-chat .chat-prompts>summary{color:var(--muted);font-size:13px;min-height:44px;line-height:1.5}
