.screen [data-payment-entry] .legon-backdrop{display:none}
.screen [data-payment-entry] .form{margin-top:4px}
.screen [data-payment-entry] .field{margin-bottom:8px}
.screen [data-payment-entry] .field>span{margin-bottom:3px}
.screen .payment-amount-row{display:flex;flex-wrap:nowrap;min-width:0;max-width:100%}
.screen .payment-currency{white-space:nowrap;word-break:normal;overflow-wrap:normal;flex-shrink:0}
.screen .payment-amount-row .amount-input{flex:1 1 0;min-width:0;width:100%;max-width:100%}
.screen [data-payment-entry] .payment-amount-row{display:flex;align-items:baseline;gap:8px;min-width:0;max-width:100%;flex-wrap:nowrap}
.screen [data-payment-entry] .payment-amount-row .payment-currency{
