 color:var(--ink);font-size:20px;font-weight:600;line-height:1.2;letter-spacing:-.4px;
}
.screen [data-payment-entry] .payment-amount-row .amount-input{
 flex:1 1 0;min-width:0;width:100%;max-width:100%;min-height:54px!important;
 font-size:40px!important;line-height:1.15;padding:4px 0!important;text-align:left;
 border-radius:6px;letter-spacing:-1.2px;font-variant-numeric:tabular-nums;
}
.screen [data-payment-entry] .payment-plan-link{padding:0;margin:2px 0 8px;background:none;border-radius:0}
.screen [data-payment-entry] .payment-plan-link .field{margin-bottom:0}
.screen [data-payment-entry] .payment-plan-link .field>span{font-size:13px;line-height:1.4;margin:0 0 4px}
.screen [data-payment-entry] .payment-plan-link select{min-height:44px;margin-top:0;padding:10px 12px;font-size:16px;line-height:1.4}
