/* Campus Pay is a task over a retained page, never a second stack of pages.
   Load after clarity-edition.css. The sheet adapter owns viewport measurements,
   focus, inert state and task history; this file only presents those states. */
:root{
 --task-sheet-curve:24px;
 --task-sheet-gutter:24px;
 --task-sheet-backdrop:rgb(17 17 17 / .42);
}
/* Renaming the retained outlet must preserve the app's original flex sizing and
   scroll surface. Its children stay mounted; inert and the scrim stop interaction. */
#task-parent-view{
 flex:1 1 auto;
 min-width:0;
 min-height:0;
 overflow-x:hidden;
 overflow-y:auto;
 background:var(--white,#fff);
}
#task-parent-view [id$="-parent-error"]{color:var(--red,#8a3027);font-size:14px;margin:15px 0}
#task-parent-view [id$="-parent-error"]:empty{display:none}
body.task-sheet-open #toast{z-index:90;bottom:calc(20px + env(safe-area-inset-bottom))}

/* Keep the retained Pay error outlet visually identical after ID isolation. */
#task-parent-view [id$="-parent-error"]{color:var(--red,#8a3027);font-size:14px;margin:15px 0}
#task-parent-view [id$="-parent-error"]:empty{display:none}

/* The app's measured horizontal frame keeps the overlay inside the phone on
   desktop as well as full-width on a real phone. Fixed positioning follows the
   visual viewport, including the phone keyboard. No parent transform or filter
   is applied, so the saved Home layout and scroll position do not change. */
#app .task-sheet-layer{
 position:fixed;
 z-index:70;
 top:var(--task-viewport-top,0px);
 left:var(--task-app-left,0px);
 width:var(--task-app-width,100%);
 height:var(--task-viewport-height,100dvh);
 max-width:460px;
 display:flex;
 align-items:flex-end;
 isolation:isolate;
 pointer-events:none;
 overflow:hidden;
}
.task-sheet-layer[hidden]{display:none!important}
.task-sheet-backdrop{
 position:absolute;
 inset:0;
 z-index:0;
 width:100%;
 height:100%;
 min-height:0;
 margin:0;
 padding:0;
 border:0;
 border-radius:0;
 background:var(--task-sheet-backdrop);
 opacity:0;
 cursor:default;
 pointer-events:auto;
 touch-action:none;
 transition:opacity var(--motion-reveal,180ms) var(--ease-focus,ease);
}
.task-sheet-layer .task-sheet-backdrop:active{transform:none}
.task-sheet{
 position:relative;
 z-index:1;
 display:flex;
 flex-direction:column;
 width:100%;
 height:min(90%,780px);
 min-height:0;
 max-height:calc(100% - max(16px,env(safe-area-inset-top)));
 margin:0;
 padding:0;
 overflow:hidden;
 border:1px solid rgb(17 17 17 / .1);
 border-bottom:0;
 border-radius:var(--task-sheet-curve) var(--task-sheet-curve) 0 0;
 background:var(--white,#fff);
 color:var(--ink,#111);
 box-shadow:0 -12px 40px rgb(17 17 17 / .08);
 pointer-events:auto;
 transform:translateY(24px);
 opacity:0;
 transition:transform var(--motion-resolve,220ms) var(--ease-focus,ease),opacity var(--motion-reveal,180ms) var(--ease-focus,ease);
}
.task-sheet:focus{outline:none}
.task-sheet-layer.is-ready .task-sheet-backdrop{opacity:1}
.task-sheet-layer.is-ready .task-sheet{transform:translateY(var(--task-drag-y,0px));opacity:1}
.task-sheet-layer.is-dragging .task-sheet{transition:none}

/* Controls remain outside the scrolling content. Back moves within this task;
   Close dismisses it. The title names the task, not its current financial state. */
.task-sheet-chrome{
 position:relative;
 display:grid;
 grid-template-columns:44px minmax(0,1fr) 44px 44px;
 align-items:center;
 gap:0 2px;
 flex:0 0 auto;
 min-height:68px;
 padding:14px 12px 6px;
 border-bottom:1px solid var(--line,#dedede);
 background:var(--white,#fff);
 color:var(--ink,#111);
 touch-action:none;
 user-select:none;
}
.task-sheet-grab{position:absolute;top:6px;left:50%;width:32px;height:4px;transform:translateX(-50%);border-radius:4px;background:#b8b8b8;pointer-events:auto}
.task-sheet-chrome #task-sheet-title{
 min-width:0;
 padding:0 6px;
 overflow-wrap:anywhere;
 font-size:15px;
 line-height:1.4;
 font-weight:600;
 letter-spacing:-.01em;
}
.task-sheet-chrome .icon-btn{
 display:inline-flex;
 align-items:center;
 justify-content:center;
 width:44px;
 min-width:44px;
 height:44px;
 min-height:44px;
 padding:10px;
 border:0;
 border-radius:50%;
 background:transparent;
 color:var(--ink,#111);
 touch-action:manipulation;
}
.task-sheet-chrome .icon-btn svg{width:22px;height:22px;stroke-width:1.8}
.task-sheet-chrome .icon-btn:focus-visible{outline:2px solid var(--ink,#111);outline-offset:-3px;box-shadow:none}
.task-sheet-chrome .icon-btn[hidden]{display:none}
.task-sheet-chrome .task-sheet-back[hidden]{display:flex;visibility:hidden;pointer-events:none}

/* One scroll surface accommodates long recipients, open calculations, increased
   text and a keyboard. Nothing is clipped to force a one-screen composition. */
.task-sheet-body,
.task-sheet-body#view{
 position:relative;
 flex:1 1 auto;
 min-width:0;
 min-height:0;
 width:100%;
 height:auto;
 max-height:none;
 overflow-x:hidden;
 overflow-y:auto;
 overscroll-behavior:contain;
 -webkit-overflow-scrolling:touch;
 scroll-padding:16px 0 calc(20px + env(safe-area-inset-bottom));
 background:var(--white,#fff);
 color:var(--ink,#111);
}
.task-sheet-body .screen,
.task-sheet-body .screen.screen-pause{
 width:100%;
 min-width:0;
 min-height:0;
 height:auto;
 max-height:none;
 padding:18px var(--task-sheet-gutter) calc(24px + env(safe-area-inset-bottom));
 overflow:visible;
 background:var(--white,#fff);
 animation:none!important;
}
.task-sheet-body .screen>.topline,
.task-sheet-body .screen>section>.topline,
.task-sheet-body .screen>.focus-review>.topline,
.task-sheet-body .screen>.focus-pause>.topline{display:none}
.task-sheet-body .page-heading{margin:0 0 18px}
.task-sheet-body .page-heading h1{font-size:1.875rem;line-height:1.15;letter-spacing:-.025em}
.task-sheet-body .page-heading p{margin-top:8px;font-size:14px;line-height:1.45}
.task-sheet-body .screen h1,
.task-sheet-body .screen h2,
.task-sheet-body .screen p,
.task-sheet-body .screen strong{overflow-wrap:break-word}
.task-sheet-body .screen .currency,
.task-sheet-body .screen .payment-currency{white-space:nowrap;word-break:normal;overflow-wrap:normal;flex-shrink:0}
.task-sheet-body .screen .primary,
.task-sheet-body .screen .secondary{min-height:52px;line-height:1.4}
.task-sheet-body .screen .text-btn,
.task-sheet-body .screen summary{min-height:44px}
.task-sheet-body .screen input:not([type=checkbox]):not([type=radio]),
.task-sheet-body .screen select,
.task-sheet-body .screen textarea{font-size:16px;scroll-margin-block:16px}
.task-sheet-body .screen .actions{gap:8px;margin-top:16px}
.task-sheet-body .screen .compact-section{margin-top:16px}
.task-sheet-body .screen .campus-code{margin:0 0 14px}
.task-sheet-body .screen .campus-code label{font-size:14px;line-height:1.45;margin-bottom:6px}
.task-sheet-body .screen .campus-code .inline{gap:8px}
.task-sheet-body .screen .campus-code .secondary{width:auto;min-width:68px;flex:0 0 auto}
.task-sheet-body .screen .campus-merchants .illustrated-row{min-height:80px}
.task-sheet-body .screen .campus-merchants .option-art{width:72px;height:60px}

/* Entry gets one small drawing, one amount, a plan link and one live sentence.
   Review is factual. The Pause retains its comparison and equivalent choices. */
.task-sheet-layer .screen[data-density] [data-payment-entry] .scene-art,
.task-sheet-layer .screen [data-payment-entry] .scene-art{height:48px!important;margin:0 auto 3px!important}
.task-sheet-body [data-payment-entry] .hero{padding:0 0 6px;gap:5px!important}
.task-sheet-body .screen [data-payment-entry] .hero>h1{font-size:1.5rem;line-height:1.2}
.task-sheet-body .screen [data-payment-entry] .hero>p{font-size:13px;line-height:1.4}
.task-sheet-body [data-payment-entry] .form{margin-top:8px}
.task-sheet-body [data-payment-entry] .field{margin-bottom:12px}
.task-sheet-body .screen [data-payment-entry] .payment-amount-row{gap:8px;flex-wrap:nowrap;align-items:baseline;min-width:0}
.task-sheet-body .screen [data-payment-entry] .payment-amount-row .payment-currency{font-size:21px;white-space:nowrap;flex:0 0 auto}
.task-sheet-body .screen [data-payment-entry] .payment-amount-row .amount-input{min-height:56px!important;font-size:2.625rem!important;line-height:1.2;padding:3px 0!important;min-width:0;flex:1 1 0}
.task-sheet-body .screen [data-payment-entry] .payment-plan-link{margin:0 0 4px;padding:0}
.task-sheet-body .screen [data-payment-entry] .payment-plan-link .field{margin-bottom:4px}
.task-sheet-body .screen [data-payment-entry] .payment-plan-link p{font-size:12px;line-height:1.45;margin-top:4px}
.task-sheet-body .screen [data-payment-entry] .payment-projection{margin:7px 0 12px}
.task-sheet-body .screen [data-payment-entry] .entry-consequence{padding:0;gap:7px}
.task-sheet-body .screen [data-payment-entry] .entry-consequence-copy{font-size:14px;line-height:1.4}
.task-sheet-body .screen [data-payment-entry] .entry-consequence-label{font-size:12px;line-height:1.4}
.task-sheet-body .screen [data-payment-entry] .form>.primary{margin-top:0}
.task-sheet-body .screen [data-payment-entry] .optional-fields{margin-top:4px}
.task-sheet-layer .screen.screen-paymentReview[data-density] .review-stage.focus-art .scene-art,
.task-sheet-layer .screen.screen-paymentReview .review-stage .scene-art{height:40px!important;margin:0!important}
.task-sheet-body .screen-paymentReview .focus-payment-title{margin:4px 0 14px}
.task-sheet-body .screen-paymentReview .focus-payment-title h1{font-size:2.75rem;line-height:1.15;margin:5px 0}
.task-sheet-body .screen-paymentReview .focus-payment-title p{font-size:16px;line-height:1.45}
.task-sheet-body .screen-paymentReview .focus-payment-title small{font-size:13px;line-height:1.45}
.task-sheet-body .screen-paymentReview .focus-receipt>div{padding:8px 0;font-size:14px}
.task-sheet-body .screen-paymentReview .focus-receipt strong{max-width:65%;overflow-wrap:anywhere}
.task-sheet-body .screen-pause .focus-pause-label{margin:0 0 10px}
.task-sheet-body .screen-pause .pause-decision-heading{grid-template-columns:52px minmax(0,1fr);gap:10px;margin-bottom:10px}
.task-sheet-layer .screen.screen-pause[data-density] .pause-decision-heading .pause-stage.focus-art .scene-art,
.task-sheet-layer .screen.screen-pause .pause-decision-heading .pause-stage .scene-art{height:52px!important;margin:0!important}
.task-sheet-body .screen-pause .pause-decision-heading .focus-pause-insight h1{font-size:1.5rem;line-height:1.2;letter-spacing:-.02em}
.task-sheet-body .screen-pause .pause-comparison{margin:11px 0;padding:11px 0}
.task-sheet-body .screen-pause .pause-comparison-values strong{font-size:1.75rem;line-height:1.25}
.task-sheet-body .screen-pause .pause-payment-context{font-size:13px;line-height:1.45;margin-bottom:10px}
.task-sheet-body .screen-pause .focus-choice{margin:10px 0 0}
.task-sheet-body .screen-pause .pause-actions{margin-top:10px}
.task-sheet-body .screen-pause .pause-decisions{gap:8px}
.task-sheet-body .screen-pause .pause-decisions .pause-equal-choice{min-height:52px;font-size:14px;line-height:1.4;padding:12px 8px}
.task-sheet-layer .screen.screen-authorize[data-density] .scene-art,
.task-sheet-layer .screen.screen-authorize .scene-art{height:56px!important;margin:0 auto 8px!important}
.task-sheet-body .screen-authorize .hero{padding:0 0 12px;gap:7px!important}
.task-sheet-body .screen-authorize .hero h1{font-size:1.875rem;line-height:1.15}
.task-sheet-body .screen-authorize .form{margin-top:12px}
.task-sheet-layer .screen.screen-paymentResult[data-density] .hero>.scene-art,
.task-sheet-layer .screen.screen-paymentResult .hero>.scene-art{height:120px!important;margin:0 auto 8px!important}
.task-sheet-body .screen-paymentResult .hero{padding:0 0 10px;margin-bottom:12px}
.task-sheet-body .screen-paymentResult .hero h1{font-size:1.875rem;line-height:1.2}
.task-sheet-body .screen-paymentResult .receipt{padding:12px 0}
.task-sheet-body .screen-paymentResult .summary-line{padding:8px 0}
.task-sheet-body .focus-footnote{font-size:12px;line-height:1.5}

/* A short viewport should surrender illustration space before text or controls.
   Keyboard-open state grows the sheet instead of hiding the focused input. */
.task-sheet-layer.task-keyboard-open .task-sheet{height:calc(100% - 8px);max-height:calc(100% - 8px);border-radius:18px 18px 0 0}
.task-sheet-layer.task-keyboard-open .task-sheet-chrome{min-height:56px;padding-top:4px;padding-bottom:4px}
.task-sheet-layer.task-keyboard-open .screen [data-payment-entry] .scene-art,
.task-sheet-layer.task-keyboard-open .screen[data-density] [data-payment-entry] .scene-art{height:24px!important;margin:0 auto 2px!important}
.task-sheet-layer.task-keyboard-open .screen [data-payment-entry] .hero{padding-bottom:3px}
.task-sheet-layer.task-keyboard-open .screen [data-payment-entry] .hero>p{font-size:13px}
@media(min-width:900px){
 #app .task-sheet-layer{top:calc(var(--task-viewport-top,0px) + 32px);height:calc(var(--task-viewport-height,100dvh) - 64px);border-radius:34px}
 .task-sheet{height:94%;max-height:calc(100% - 16px)}
}
@media(max-width:359px){
 :root{--task-sheet-gutter:18px}
 .task-sheet-chrome{padding-left:8px;padding-right:8px;gap:0}
 .task-sheet-chrome #task-sheet-title{padding:0 4px;font-size:14px}
 .task-sheet-body .screen [data-payment-entry] .payment-amount-row .amount-input{font-size:2.375rem!important}
 .task-sheet-body .screen-pause .pause-decision-heading{grid-template-columns:44px minmax(0,1fr);gap:8px}
 .task-sheet-layer .screen.screen-pause[data-density] .pause-decision-heading .pause-stage.focus-art .scene-art,
 .task-sheet-layer .screen.screen-pause .pause-decision-heading .pause-stage .scene-art{height:44px!important}
 .task-sheet-body .screen-pause .pause-decision-heading .focus-pause-insight h1{font-size:1.375rem}
 .task-sheet-body .screen-pause .pause-comparison-values{gap:5px;grid-template-columns:minmax(0,1fr) 18px minmax(0,1fr)}
 .task-sheet-body .screen-pause .pause-comparison-values strong{font-size:1.625rem}
}
@media(max-height:700px){
 .task-sheet{height:94%;max-height:calc(100% - 12px)}
 .task-sheet-body .screen,.task-sheet-body .screen.screen-pause{padding-top:12px}
 .task-sheet-body .page-heading{margin-bottom:12px}
 .task-sheet-layer .screen.screen-paymentResult[data-density] .hero>.scene-art,
 .task-sheet-layer .screen.screen-paymentResult .hero>.scene-art{height:96px!important}
}
@media(hover:hover){.task-sheet-chrome .icon-btn:hover{background:var(--soft,#f5f5f5)}}
@media(prefers-reduced-motion:reduce){
 .task-sheet-layer .task-sheet,.task-sheet-layer .task-sheet-backdrop{transition:none!important;transform:none!important;opacity:1}
 .task-sheet-body,.task-sheet-body *{scroll-behavior:auto!important}
}

/* Source: clarity-bold.css | sha256:6316baac11c7031261c25d2de55e3ecaa321d2e340a19a75e46b911891d5fd12 */
/* Lumo's expressive pass: campus scenes, open type and restrained insight accents.
   Keep last, after task-sheet.css. Real figures and financial rules remain in JS. */
:root{
 --bold-hero-size:clamp(184px,26dvh,220px);
 --bold-intro-size:clamp(220px,31dvh,260px);
 --bold-home-size:clamp(184px,26dvh,216px);
 --bold-chat-size:clamp(184px,26dvh,216px);
 --art-intro-size:var(--bold-intro-size);
 --art-everyday-size:var(--bold-hero-size);
 --art-home-size:var(--bold-home-size);
 --art-conversation-intro-size:var(--bold-chat-size);
 --art-entry-size:48px;
 --art-review-size:40px;
 --art-pause-size:60px;
 --art-result-size:148px;
 --bold-lens-colour:#cfef59;
}
body{background:#ececec}
.screen{font-size:16px;line-height:1.5;letter-spacing:0}
.screen h1,.screen h2,.screen h3{font-weight:700;color:var(--ink,#111)}
.screen .page-heading h1,
.screen[data-density] .page-heading h1,
.screen .destination-heading h1,
.screen .focus-pay-heading h1,
.screen .focus-story-heading h1{font-size:clamp(2rem,8.8vw,2.5rem);font-weight:700;line-height:1.1;letter-spacing:-.03em}
.screen .page-heading>p,
.screen .destination-heading>p,
.screen .focus-pay-heading>p,
.screen .focus-story-heading>p{font-size:15px;line-height:1.5;margin-top:10px;color:var(--muted,#555)}
.screen .small,.screen small{font-size:14px;line-height:1.5}
.screen .tiny{font-size:12px;line-height:1.5}
.screen .row-copy strong{font-size:17px;line-height:1.35;font-weight:600}
.screen .row-copy small,.screen .illustrated-row small{font-size:14px;line-height:1.45}
.screen .row{min-height:70px;padding:14px 0}
.screen .primary,.screen .secondary,.screen .danger{min-height:54px;font-size:16px;line-height:1.4;font-weight:700;padding:14px 16px;border-radius:12px;box-shadow:none}
.screen .text-btn,.screen .link{min-height:44px;font-size:15px;line-height:1.45;font-weight:500}
.screen input:not([type=checkbox]):not([type=radio]),.screen select,.screen textarea{font-size:16px;line-height:1.5;min-height:52px}
.screen label.field,.screen .field>span{font-size:15px;line-height:1.45;font-weight:500}
.screen .warning,.screen .notice{font-size:15px;line-height:1.5}
.screen .eyebrow{font-size:11px;line-height:1.45;font-weight:600;letter-spacing:.9px}
/* Older layers used green for input focus and spending-category graphics.
   Keep those functional states neutral so lime retains its insight meaning. */
.screen input:focus,.screen select:focus,.screen textarea:focus{border-color:var(--ink);box-shadow:0 0 0 3px #11111120}
.screen-pay .pay-tab-panel:focus-visible{outline-color:var(--ink)}
.screen-story .focus-category-track{background:#ececec}
.screen-story .focus-category i,.screen-story .focus-category-track>span{filter:grayscale(1)}

/* Each scene has a readable foreground gesture and one restrained campus layer.
   The figure always uses contain: no body, hand or object is cropped to fill.
   The grayscale applies only to the setting, preserving the textile colours. */
.screen .scene-art.bold-scene,
.screen[data-density] .scene-art.bold-scene{
 position:relative;
 display:block;
 width:100%;
 max-width:100%;
 height:var(--bold-hero-size)!important;
 min-height:0;
 margin:10px auto 16px!important;
 padding:0;
 overflow:visible;
 isolation:isolate;
 background:none;
 mix-blend-mode:normal;
 flex-shrink:0;
}
.bold-scene>.legon-backdrop{
 position:absolute;
 inset:5% 0 0;
 z-index:0;
 display:block;
 width:100%;
 height:95%;
 overflow:hidden;
 pointer-events:none;
 opacity:.3;
 filter:grayscale(1);
 -webkit-mask-image:linear-gradient(to bottom,transparent 0%,#000 15%,#000 68%,transparent 100%);
 mask-image:linear-gradient(to bottom,transparent 0%,#000 15%,#000 68%,transparent 100%);
}
.bold-scene .legon-backdrop-image{
 display:block;
 width:100%;
 height:100%;
 max-width:none;
 max-height:none;
 object-fit:cover;
 object-position:center;
 filter:grayscale(1) contrast(.9) brightness(1.08);
 mix-blend-mode:normal;
}
.bold-scene>.expressive-figure{
 position:relative;
 z-index:1;
 display:block;
 width:100%;
 height:100%;
 margin:0;
 overflow:visible;
 pointer-events:none;
}
.bold-scene .bold-figure-image{
 display:block;
 width:100%;
 height:100%;
 max-width:100%;
 max-height:100%;
 object-fit:contain;
 object-position:center bottom;
 filter:none;
 mix-blend-mode:normal;
}
.screen .scene-art.bold-scene::before,.screen .scene-art.bold-scene::after{content:none;display:none}
.screen .scene-art.bold-scene.scene-size-intro,
.screen[data-density] .scene-art.bold-scene.scene-size-intro{height:var(--bold-intro-size)!important}
.screen .scene-art.bold-scene.scene-size-decision,
.screen[data-density] .scene-art.bold-scene.scene-size-decision{height:64px!important;margin:0 auto 8px!important}
.screen.screen-welcome .welcome-illustration,
.screen.screen-welcome .welcome-illustration .scene-art.bold-scene,
.screen.screen-welcome[data-density] .welcome-illustration .scene-art.bold-scene{height:var(--bold-intro-size)!important;margin:4px auto 20px!important}
.screen-welcome .welcome-screen>h1{font-size:clamp(2.5rem,10.5vw,3rem);font-weight:700;line-height:1.05;letter-spacing:-.035em;max-width:11ch}
.screen-welcome .welcome-screen>.muted{font-size:16px;line-height:1.5;max-width:32ch}
.screen-home .home-stage .scene-art.bold-scene,
.screen-home[data-density] .home-stage .scene-art.bold-scene,
.screen-home:has(.has-saved-plan) .home-stage .scene-art.bold-scene{height:var(--bold-home-size)!important;margin:8px 0 16px!important}
.screen-home .home-stage{margin:0 0 12px}
.screen-home .home-intro{margin:8px 0 14px}
.screen-home .home-intro p{font-size:22px;font-weight:600;line-height:1.25;letter-spacing:-.02em}
.screen-home .home-intro>span{font-size:13px;line-height:1.4}
.screen-home .has-saved-plan .focus-amount{font-size:25px;font-weight:600;line-height:1.2}
.screen .destination-stage .scene-art.bold-scene,
.screen[data-density] .destination-stage .scene-art.bold-scene,
.screen-pay .focus-pay-art .scene-art.bold-scene{height:var(--bold-hero-size)!important;margin:10px 0 18px!important}
.screen-chat .page-heading>.scene-art.bold-scene,
.screen-chat[data-density] .page-heading>.scene-art.bold-scene,
.screen-chat .chat-illustration .scene-art.bold-scene,
.screen-chat[data-density] .chat-illustration .scene-art.bold-scene{height:var(--bold-chat-size)!important;margin:10px 0 16px!important}
.screen-chat .chat-has-conversation .scene-art.bold-scene{display:none!important}
.screen-chat .chat-workspace:not(.chat-has-conversation) .page-heading h1{font-size:2.5rem;font-weight:700;line-height:1.08;letter-spacing:-.03em}
.screen-chat .chat-has-conversation .page-heading h1{font-size:26px;font-weight:600;line-height:1.2}
.screen .empty .scene-art.bold-scene{height:var(--bold-intro-size)!important;margin:8px auto 18px!important}
.screen .option-art.bold-scene,
.screen[data-density] .option-art.bold-scene,
.screen .option-art .scene-art.bold-scene{height:64px!important;margin:0!important}
.screen .illustrated-row>.option-art.bold-scene{width:76px;height:64px!important}
.screen .option-art.bold-scene>.legon-backdrop{opacity:.18}

/* Legacy lens hooks now identify real conclusions, not decorative containers.
   Lime sits behind the useful figure or sentence. No large ring or reserved
   ring space remains. Repeated standalone ring markers are removed too. */
.lumo-lens{
 position:relative;
 min-width:0;
 overflow:visible;
}
.lumo-lens::before{
 content:none;
 display:none;
 pointer-events:none;
}
.lumo-lens::after{content:none;display:none;pointer-events:none}
.lumo-lens-value{font-variant-numeric:lining-nums tabular-nums}
.screen .clarity-ring{display:none!important}
.intelligence-note{font-size:14px;line-height:1.5;color:var(--muted,#555)}
.screen-home .home-plan-summary.lumo-lens,
.screen-home .home-plan-summary.lumo-lens[data-decision-state=shortfall]{min-height:0;margin:7px 0 4px;padding:16px 0 6px;border:0;border-top:1px solid var(--line);background:none;border-radius:0;gap:8px}
.screen-home .home-plan-summary.lumo-lens small{font-size:15px;line-height:1.4;font-weight:600}
.screen-home .home-plan-summary.lumo-lens strong.lumo-lens-value{display:table;background:linear-gradient(transparent 66%,var(--bold-lens-colour) 66%,var(--bold-lens-colour) 94%,transparent 94%);font-size:clamp(2.75rem,12.8vw,3.375rem);font-weight:700;line-height:1.15;letter-spacing:-.035em;margin:9px 0 10px;padding:0 3px 2px 0;max-width:100%;overflow-wrap:anywhere;box-decoration-break:clone;-webkit-box-decoration-break:clone}
.screen-home .home-plan-summary.lumo-lens .home-plan-math{display:block;font-size:14px;line-height:1.5;color:var(--muted);max-width:32ch}
.screen-home .home-plan-summary.lumo-lens .home-plan-math b{color:var(--ink);font-weight:500}
.screen-home .home-plan-period{font-size:14px;line-height:1.5;padding-top:12px;margin:0}
.screen-home .privacy-hint{font-size:12px;line-height:1.45}
.screen-home .focus-main-actions{gap:10px}
.screen-home .focus-main-actions button{min-height:54px;font-size:16px;font-weight:700}
.screen-home .focus-small-actions{gap:20px;margin:2px 0 12px}
.screen-home .focus-small-actions .text-btn{font-size:15px;min-height:44px}
.screen .plan-room.lumo-lens{min-height:0;padding:16px 0}
.screen .plan-total.lumo-lens{min-height:0;padding:0}
.screen .plan-room.lumo-lens>strong{font-size:3rem;font-weight:700;line-height:1.15}
.screen .plan-room.lumo-lens .lumo-lens-value,.screen .plan-total.lumo-lens .lumo-lens-value{background:none}
.screen .plan-room.lumo-lens>p{font-size:14px;line-height:1.5}
.screen-pause .pause-comparison-after.lumo-lens{display:block;min-height:0;padding:0;text-align:left}
.screen-pause .pause-comparison-after.lumo-lens .comparison-label{max-width:none;margin-bottom:4px;font-size:12px;line-height:1.4}
.screen-pause .pause-comparison-after.lumo-lens strong{display:inline-block;background:linear-gradient(transparent 66%,var(--bold-lens-colour) 66%,var(--bold-lens-colour) 94%,transparent 94%);padding:0 3px 1px 0;font-weight:700;font-size:1.875rem;line-height:1.2;box-decoration-break:clone;-webkit-box-decoration-break:clone}
.screen-pause .pause-comparison-after.lumo-lens>small{margin:4px 0 0;max-width:none;font-size:12px;line-height:1.4}
.screen-pause .pause-comparison-before strong{font-weight:600}
