/* Native task refinement. Load last. Preserve identity and financial behavior;
   content determines height, and important text never shrinks to force a fit. */
:root{--native-gutter:22px;--native-control:54px;--native-home-art:64px}
body{height:auto;min-height:100dvh;overflow:auto}
#app{display:flex;flex-direction:column;min-height:0;height:100dvh}
#view:not(.task-sheet-body),#task-parent-view{flex:1 1 auto;min-height:0;min-width:0;overflow-x:hidden;overflow-y:auto}
#app>.prototype-boundary{flex:0 0 auto;padding:2px 10px 4px;font-size:.6875rem;line-height:1.4}
#app>#nav{flex-shrink:0}
body.task-sheet-open{overflow:hidden}
@media(max-width:899px){
 body{padding:0;background:#fff}
 #app{width:100%;max-width:none;margin:0;padding-top:env(safe-area-inset-top);border-radius:0;box-shadow:none}
 #app .task-sheet-layer{max-width:none}
}
@media(min-width:900px){#app{height:calc(100dvh - 64px)}}

