/* Chat is a stable flex workspace. The conversation scrolls independently;
   its composer remains above navigation and the actual visible keyboard. */
#app[data-route=chat]{height:var(--chat-viewport-height,100dvh);top:var(--chat-viewport-top,0px)}
#app[data-route=chat]>#view:not(.task-sheet-body){overflow:hidden}
#app[data-route=chat] .screen.screen-chat,
#app[data-route=chat] .screen.screen-chat[data-density]{display:flex;flex-direction:column;min-height:0;height:100%;max-height:100%;padding:8px var(--native-gutter) 8px;overflow:hidden}
#app[data-route=chat] .chat-workspace{display:flex;flex-direction:column;min-height:0;height:100%;max-height:100%;width:100%;overflow-x:hidden;overflow-y:auto;overscroll-behavior:contain;scroll-padding-bottom:64px}
#app[data-route=chat] .chat-workspace>.topline{flex:0 0 auto;min-height:44px;margin:0 0 8px}
#app[data-route=chat] .chat-workspace>.page-heading{display:grid;grid-template-columns:minmax(0,1fr) 72px;column-gap:12px;align-items:center;flex:0 0 auto;min-width:0;margin:0 0 8px}
#app[data-route=chat] .chat-workspace>.page-heading .chat-illustration{grid-column:2;grid-row:1 / span 2;width:72px;margin:0}
#app[data-route=chat] .screen-chat .chat-illustration .scene-art,
#app[data-route=chat] .screen-chat[data-density] .chat-illustration .scene-art{height:72px!important;margin:0!important}
#app[data-route=chat] .chat-workspace>.page-heading h1{grid-column:1;font-size:1.75rem;line-height:1.15;font-weight:600;letter-spacing:-.02em;max-width:none;margin:0}
#app[data-route=chat] .chat-workspace>.page-heading>p{grid-column:1;font-size:.875rem;line-height:1.45;margin-top:6px}
#app[data-route=chat] .chat-has-conversation>.page-heading{display:block;margin-bottom:6px}
#app[data-route=chat] .chat-has-conversation>.page-heading h1{font-size:1.5rem;line-height:1.2}
#app[data-route=chat] .chat-has-conversation>.page-heading .chat-illustration,
#app[data-route=chat] .chat-has-conversation>.page-heading>p{display:none}
#app[data-route=chat] #chat-thread{flex:1 1 auto;min-height:0!important;height:auto;max-height:none;overflow-x:hidden;overflow-y:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;scroll-padding-block:12px;padding:0 0 8px}
#app[data-route=chat] .chat-has-conversation #chat-thread{min-height:6rem!important}
#app[data-route=chat] .chat-turn{margin:10px 0 16px}
#app[data-route=chat] .chat-bubble.user{font-size:.9375rem;line-height:1.45;padding:10px 12px;margin:4px 0 10px}
#app[data-route=chat] .chat-reply{padding:8px 0;margin:0}
#app[data-route=chat] .chat-reply .lead{font-size:1.125rem;line-height:1.45;font-weight:600}
#app[data-route=chat] .chat-reply.lumo-lens[data-insight] .lead.lumo-lens-value{font-size:1.25rem;line-height:1.4;font-weight:600}
#app[data-route=chat] .chat-reply .impact-secondary{font-size:.9375rem;line-height:1.5;margin-top:9px}
#app[data-route=chat] .chat-reply-actions{gap:0 16px;margin-top:8px}
#app[data-route=chat] .chat-reply-actions .text-btn,
#app[data-route=chat] .chat-calculation-link{min-height:44px;font-size:.875rem;line-height:1.45}
#app[data-route=chat] .chat-tools{flex:0 1 auto;display:block;min-width:0;min-height:44px;max-height:min(15rem,calc(var(--chat-viewport-height,100dvh) / 3));overflow-x:hidden;overflow-y:auto;overscroll-behavior:contain;margin:0 0 6px}
#app[data-route=chat] .chat-tools .chat-context,
#app[data-route=chat] .chat-tools .chat-prompts{margin:0;padding:0;border:0}
#app[data-route=chat] .chat-tools summary{min-height:44px;padding:10px 0;font-size:.8125rem;line-height:1.45;font-weight:500}
#app[data-route=chat] .chat-tools .chat-prompts .chips{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:0 0 6px}
#app[data-route=chat] .chat-tools .chat-prompts .chip{min-height:44px;padding:8px 10px;border:1px solid var(--line);border-radius:10px;font-size:.875rem;line-height:1.4;text-align:left;background:#fff}
#app[data-route=chat] .chat-has-conversation>.chat-tools{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 12px}
#app[data-route=chat] .chat-has-conversation>.chat-tools>details[open]{grid-column:1 / -1}
#app[data-route=chat] .chat-entry{position:sticky;bottom:0;z-index:3;flex:0 0 auto;min-width:0;min-height:56px;margin:0;padding:4px;gap:4px;border:1.5px solid var(--ink);border-radius:14px;background:#fff}
#app[data-route=chat] .chat-entry input{min-width:0;min-height:46px;font-size:1rem;line-height:1.5}
#app[data-route=chat] .chat-entry button{width:46px;min-width:46px;height:46px;min-height:46px}
#app[data-route=chat] .chat-boundary{flex:0 0 auto;font-size:.6875rem;line-height:1.4;margin:6px 0 0!important}
