#app.chat-keyboard-open[data-route=chat] .chat-workspace>.topline{margin-bottom:4px}
#app.chat-keyboard-open[data-route=chat] .chat-boundary{position:absolute;width:1px;height:1px;margin:-1px!important;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}
.chat-calculation-page .chat-calculation-body{font-size:.9375rem;line-height:1.5}
.chat-calculation-body dl{margin:0}
.chat-calculation-body dl>div{display:flex;align-items:baseline;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid var(--line)}
.chat-calculation-body dt{flex:1;min-width:0;color:var(--muted)}
.chat-calculation-body dd{margin:0;max-width:55%;text-align:right;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}
.chat-calculation-body p{margin-top:12px;font-size:.875rem;line-height:1.5}
@media(min-width:900px){#app[data-route=chat]{height:calc(var(--chat-viewport-height,100dvh) - 64px)}}

/* These ranges are layout targets, not a claim of device rendering validation.
   Text stays the same size; smaller screens surrender art and spare spacing. */
@media(max-width:379px){:root{--native-gutter:18px;--native-home-art:56px}}
@media(min-width:400px) and (max-width:899px){:root{--native-gutter:24px;--native-home-art:72px}}
@media(max-width:379px) and (max-height:700px){
 :root{--native-home-art:48px}
 #app .screen-home .home-greeting{margin-bottom:4px}
 #app .screen-home .home-overview{gap:8px;margin-bottom:4px}
 #app .screen-home .home-plan-summary{padding-top:8px}
 #app .screen-home .focus-small-actions{margin-bottom:4px}
}
@media(prefers-reduced-motion:reduce){
 #app .task-sheet-layer .task-sheet,#app .task-sheet-layer .task-sheet-body .screen{animation:none!important;transition:none!important}
 #app[data-route=chat] #chat-thread{scroll-behavior:auto!important}
}

/* While typing, the next payment action stays in the visible scroll surface.
   This is ordinary sticky content, never a fake keyboard or fixed overlay. */
#app .task-sheet-layer.task-keyboard-open .task-sheet-body#view{scroll-padding-bottom:calc(92px + env(safe-area-inset-bottom))}
#app .task-sheet-layer.task-keyboard-open .screen input,
#app .task-sheet-layer.task-keyboard-open .screen select,
#app .task-sheet-layer.task-keyboard-open .screen textarea{scroll-margin-bottom:92px}
#app .task-sheet-layer.task-keyboard-open .screen form>button[type=submit].primary{position:sticky;bottom:0;z-index:2;box-shadow:0 0 0 7px var(--white,#fff)}
.payment-result-compact .result-mark{background:var(--white,#fff);color:var(--ink,#111);border:1.5px solid var(--ink,#111)}
.payment-result-compact[data-payment-state=confirmed] .result-mark{background:var(--ink,#111);color:var(--white,#fff)}

/* Three Home groups: money now, receiving actions and money story. */
/* Setup and access screens share a text edge. Labels are explicit spans;
   code digits stay centred, while their labels follow the other fields. */
#app .screen .onboarding-page{width:100%;min-width:0;text-align:left}
#app .screen .onboarding-page>.topline{display:grid;grid-template-columns:44px minmax(0,1fr) 44px;align-items:center;gap:8px;margin:0 0 12px}
#app .screen .onboarding-page>.topline>.eyebrow{min-width:0;text-align:center;overflow-wrap:anywhere}
#app .screen .onboarding-page .page-heading{width:100%;min-width:0;text-align:left}
#app .screen .onboarding-page .page-heading h1,
#app .screen .onboarding-page .page-heading>p{max-width:none;text-align:left;overflow-wrap:anywhere}
#app .screen .onboarding-page .form,
#app .screen .onboarding-page .field{width:100%;min-width:0;text-align:left}
#app .screen .onboarding-page .field>span{display:block;margin-bottom:8px;font-size:.875rem;line-height:1.5;font-weight:500;text-align:left}
#app .screen .onboarding-page .input:not(.code-input),
#app .screen .onboarding-page select,
