#app .simple-plan-setup .first-plan-math dt{min-width:0;overflow-wrap:anywhere}
#app .simple-plan-setup .first-plan-math dd{margin:0;text-align:right;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
#app .simple-plan-setup .optional-fields{margin:4px 0}
#app .simple-plan-setup .optional-fields>summary{min-height:44px;font-size:.875rem;padding:11px 0;line-height:1.5}
#app .simple-plan-setup .first-plan-extras{display:flex;flex-wrap:wrap;gap:8px}
/* Review has one primary decision; editing and returning later share a row. */
#app .task-sheet-layer .simple-plan-review .actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
#app .task-sheet-layer .simple-plan-review .actions>.primary{grid-column:1/-1}
#app .task-sheet-layer .simple-plan-review .actions>.secondary,#app .task-sheet-layer .simple-plan-review .actions>.text-btn{min-height:44px;padding:9px 8px}

#app .simple-plan-page .destination-heading h1{font-size:1.75rem;line-height:1.2}
