#app .simple-plan-benefit .plan-benefit-uses p{font-size:.9375rem;line-height:1.5;margin:3px 0 0;color:var(--muted)}
#app .simple-plan-benefit .plan-benefit-example-consequence{font-size:1rem;line-height:1.45;font-weight:600;margin:12px 0}
