#app .simple-plan-benefit .plan-benefit-comparison>div{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid var(--line);padding:10px 0;font-size:.9375rem;line-height:1.5}
#app .simple-plan-benefit .plan-benefit-comparison dd{margin:0;text-align:right;font-weight:500;font-variant-numeric:tabular-nums}
#app .simple-plan-benefit .plan-benefit-footnote{font-size:.875rem;line-height:1.5;margin:12px 0 0}

