/* Source: ui-consistency.css | sha256:20865a69c597376f779988d63ae8e68167a8bdd43ee3d1024c3c371a55f0819a */
/* Shared finishing rules. Home owns its financial hierarchy; sheets and long
   conversations retain their own layout and scrolling behavior. */
:root{
 --ui-title:2rem;
 --ui-sheet-title:1.5rem;
 --ui-support:.9375rem;
 --ui-label:.875rem;
 --ui-action:1rem;
 --ui-action-compact:.875rem;
 --ui-control-curve:16px;
 --ui-panel-curve:24px;
 --ui-section-gap:20px;
 --ui-related-gap:12px;
}

/* A main destination title, a compact task title, then supporting copy. */
#app .screen :is(.destination-heading,.focus-pay-heading,.focus-story-heading,.plan-hub-heading)>h1,
#app .screen:not(.screen-home):not(.screen-pause) .page-heading>h1,
#app .screen .onboarding-page .page-heading>h1{
 font-size:var(--ui-title);line-height:1.18;font-weight:700;
 letter-spacing:-.035em;text-align:left;
}
#app .screen :is(.destination-heading,.focus-pay-heading,.focus-story-heading,.plan-hub-heading)>p,
#app .screen:not(.screen-home):not(.screen-pause) .page-heading>p{
 font-size:var(--ui-support);line-height:1.5;font-weight:400;
 color:var(--muted);letter-spacing:0;margin-top:8px;
}
#app .task-sheet-layer .screen .page-heading>h1,
#app .task-sheet-layer .screen[data-density] .page-heading>h1,
#app .simple-plan-setup .page-heading>h1{
 font-size:var(--ui-sheet-title);line-height:1.22;font-weight:700;
 letter-spacing:-.025em;text-align:left;
}
#app[data-route=chat] .chat-workspace>.page-heading h1{
 font-size:var(--ui-title);line-height:1.18;font-weight:700;letter-spacing:-.035em;
}
#app[data-route=chat] .screen .chat-has-conversation>.page-heading h1{
 font-size:var(--ui-sheet-title);line-height:1.22;
}

/* Task actions share one shape. Card actions have a compact, still readable
   role rather than inheriting the 12px labels of an older composition. */
#app .screen:not(.screen-home):not(.screen-pause) :is(.primary,.secondary,.danger),
#app .task-sheet-layer .screen:not(.screen-pause) :is(.primary,.secondary,.danger){
 min-height:52px;border-radius:var(--ui-control-curve);padding:12px 16px;
 font-size:var(--ui-action);line-height:1.4;font-weight:700;letter-spacing:-.015em;
}
#app .screen:not(.screen-home):not(.screen-pause) .plan-hub-actions>button{
 min-height:48px;border-radius:var(--ui-control-curve);padding:10px 8px;
 font-size:var(--ui-action-compact);line-height:1.4;font-weight:700;
}
#app .screen:not(.screen-pause) .actions>.text-btn,
#app .screen .destination-footer>.text-btn,
#app .screen .plan-hub-detail-actions>.text-btn{
 min-height:44px;font-size:var(--ui-label);line-height:1.45;font-weight:600;
}
#app .screen .icon-btn{
 min-width:44px;min-height:44px;border-radius:var(--ui-control-curve);
}
#app .screen .icon-btn svg{width:21px;height:21px;stroke-width:1.9}

/* A label always reads as a label, including after a form enters a sheet. */
#app .screen .field>span,
#app .task-sheet-layer .screen .field>span{
 font-size:var(--ui-label);line-height:1.45;font-weight:600;
 color:var(--ink);letter-spacing:0;margin-bottom:7px;text-align:left;
}
#app .screen input.input:not(.amount-input):not(.code-input):not([type=password]),
#app .screen select.input,
#app .screen textarea.input{
 min-height:52px;border-radius:var(--ui-control-curve);
 font-size:1rem;line-height:1.5;border-color:var(--control-line);
}
#app .screen:not(.screen-pause) .field{margin-bottom:16px}
#app .task-sheet-layer .screen:not(.screen-pause) .field{margin-bottom:12px}
#app .screen :is(.focus-details,.screen-explainer,.optional-fields,.plan-hub-details)>summary{
 min-height:44px;font-size:var(--ui-label);line-height:1.45;font-weight:600;
 color:var(--green-ink);padding-top:11px;padding-bottom:11px;
}

/* Cards, record rows and explanations repeat the same construction. */
#app .screen:not(.screen-home) :is(.card,.receipt,.account-detail-card){
 border-radius:var(--ui-panel-curve);border-color:var(--line);
}
#app .screen:not(.screen-home) :is(.notice,.soft,.warning){
 border-radius:var(--ui-control-curve);
}
#app .screen .goal-summary.card{
 display:block;width:100%;text-align:left;padding:16px;margin:10px 0;
}
#app .screen .goal-summary.card h3{font-size:1rem;line-height:1.4;font-weight:700;margin:0}
#app .screen .goal-summary.card p{font-size:var(--ui-label);line-height:1.5;margin:6px 0 0}
#app .screen .goal-summary.card .progress{margin-top:12px}
#app .screen .receipt .summary-line,
#app .screen .account-detail-card dl>div{
