}
#app .screen .receipt .summary-line>strong{max-width:65%;overflow-wrap:anywhere}
#app .screen .account-detail-card dd{margin:0}
#app .screen .account-details-page>h2{font-size:1.25rem;line-height:1.3;font-weight:600}

/* One outcome symbol. State colours and truthful status copy remain owned by
   the existing result views. No motion or authorisation gate changes here. */
#app .screen-paymentResult .success-mark{
 width:56px;height:56px;min-width:56px;margin:0 auto 14px;
}
#app .screen-paymentResult .success-mark svg{width:28px;height:28px}
#app .task-sheet-layer .screen-paymentResult:has(>.hero h1)>.page-heading{
 display:none!important; /* The sheet title already says Transfer result. */
}
#app .screen-paymentResult>.hero>h1{
 font-size:var(--ui-sheet-title);line-height:1.22;letter-spacing:-.025em;
 font-weight:700;text-align:center;
}
#app .screen-paymentResult>.hero>p{font-size:1rem;line-height:1.5;text-align:center}
#app .screen :is(.bank-funding-result,.funding-budget-prompt) .notice>.avatar{
 width:40px;height:40px;min-width:40px;border-radius:50%;margin:0 0 10px;
}
#app .screen :is(.bank-funding-result,.funding-budget-prompt) .notice>.avatar svg{
 width:24px;height:24px;
}

@media(max-height:700px){
