/* QR ink stays black on white in every edition for reliable scanning. */
#app .personal-qr-page{max-width:100%;min-width:0}
#app .personal-qr-page .page-heading{margin-bottom:14px}
#app .personal-qr-page .page-heading>.scene-art{display:none!important}
#app .personal-qr-page .page-heading h1{font-size:28px;line-height:1.12}
#app .personal-qr-card{display:flex;flex-direction:column;align-items:center;gap:10px;margin:4px auto 18px;padding:14px;background:#fff;color:#111;border:1px solid var(--line,#e1e3dc);border-radius:22px;max-width:290px}
#app .lumo-personal-qr{display:block;max-width:100%;height:auto;flex:0 0 auto}
#app .personal-qr-card figcaption{display:flex;flex-direction:column;align-items:center;gap:4px;text-align:center;max-width:100%;overflow-wrap:anywhere}
#app .personal-qr-card figcaption strong{font-size:18px;line-height:1.25}
#app .personal-qr-card figcaption span{font-size:13px;line-height:1.35;color:#505050}
#app .personal-qr-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}
#app .personal-qr-actions button{display:flex;align-items:center;justify-content:center;gap:8px;min-width:0;min-height:48px;padding:12px 8px;white-space:normal}
#app .personal-qr-page>.text-btn{display:block;margin:10px auto 0;min-height:44px}
#app .personal-qr-note{font-size:12px;line-height:1.4;color:var(--muted,#64705f);text-align:center;margin:8px 0 0}
#app .personal-qr-recipient-note{font-size:12px;line-height:1.45;color:var(--muted,#64705f);border-left:2px solid var(--ink,#20261e);padding:4px 0 4px 10px;margin:8px 0 12px}
#app .personal-qr-shortcut{margin:6px 0 10px}
#app .personal-qr-shortcut .row{padding-block:10px}
@media(max-height:700px){
 #app .personal-qr-card{padding:8px;margin-bottom:12px;gap:7px;max-width:240px}
 #app .lumo-personal-qr{width:184px}
 #app .personal-qr-page .page-heading{margin-bottom:10px}
 #app .personal-qr-card figcaption strong{font-size:16px}
}
@media(max-width:340px){#app .personal-qr-actions button{font-size:13px;gap:5px}}

/* Scanner surfaces follow the edition while QR symbols retain plain ink. */
body.minna-edition #app .personal-qr-card{border-radius:4px}
body.minna-edition #app .qr-camera{background:#151515;border-color:#333}
body.minna-edition #app .qr-viewfinder{border-color:#fff}
body.minna-edition #app .qr-camera-label{background:#111e}
body.minna-edition #app .qr-photo-choice:focus-within{outline-color:#111}
body.hibiscus-edition #app .qr-camera{background:#4a1d4f;border-color:#4a1d4f}
body.hibiscus-edition #app .qr-viewfinder{border-color:#dceeb4}
body.hibiscus-edition #app .qr-camera-label{background:#4a1d4fe6}

/* Source: qr-floating.css | sha256:b3ec29baa65513deccd6b561489235f1e046eb16d4247c2b52d4aae6181e864b */
/* The QR shortcut belongs to the header, with a stable corner position. */
#lumo-scan-qr.lumo-qr-corner{position:static;display:inline-flex;align-items:center;justify-content:center;flex:0 0 40px;width:40px;min-width:40px;height:40px;min-height:40px;margin:0;padding:9px;border:1px solid transparent;border-radius:12px;background:var(--soft,#eef1e8);color:var(--ink,#20261e);font:inherit;box-shadow:none;cursor:pointer;touch-action:manipulation;transform:none}
#lumo-scan-qr.lumo-qr-corner>svg{display:block;width:22px;height:22px;flex:none}
#lumo-scan-qr[hidden]{display:none!important}
#lumo-scan-qr:focus-visible{outline:2px solid var(--ink,#20261e);outline-offset:2px}
#app .task-sheet-chrome.has-qr-corner{grid-template-columns:40px minmax(0,1fr) 40px 40px 40px}
#app .task-sheet-chrome.has-qr-corner .icon-btn{width:40px;min-width:40px}
#app .lumo-qr-corner-bar{display:flex;justify-content:flex-end;min-height:44px;margin:0 0 8px}
body.minna-edition #lumo-scan-qr{background:#f3f3f3;color:#111;border-radius:2px}
body.hibiscus-edition #lumo-scan-qr{background:var(--hibiscus-soft,#f0e3f1);color:var(--ink,#4a1d4f);border-radius:50%}

