/* Source: product-finish.css | sha256:ba01a58da3a6b128de99d8d1e1d4a8fac4e526267cdd10eb803cef7102a667b4 */
/* Final, bounded presentation corrections. Edition fonts, artwork, financial
   amounts, Home privacy geometry and the existing scroll shell stay intact. */

/* A native task has one navigation row. Device/status .topline rows remain. */
body #app .task-sheet-body .product-legacy-nav[hidden]{display:none!important}
body #app .task-sheet-body .page-heading>.product-title-echo{
 position:absolute!important;width:1px!important;height:1px!important;
 min-width:0!important;min-height:0!important;padding:0!important;margin:-1px!important;
 overflow:hidden!important;clip:rect(0,0,0,0)!important;clip-path:inset(50%)!important;
 white-space:nowrap!important;border:0!important;
}
body #app .task-sheet-body .page-heading.product-title-only{margin:0!important;padding:0!important}

/* Comfortable utility hit areas; the existing icon artwork stays 18–22px. */
body #app .screen :is(.hibiscus-root-chat,.hibiscus-home-chat-entry),
body #app .screen .home-header-actions :is(.icon-btn,.avatar),
body #app .screen .hibiscus-header-notifications,
body #app #lumo-scan-qr.lumo-qr-corner{
 flex:0 0 44px!important;width:44px!important;min-width:44px!important;
 height:44px!important;min-height:44px!important;
}
body #app .screen .topline>.icon-btn,
body #app .task-sheet-chrome>.icon-btn{
 width:44px!important;min-width:44px!important;height:44px!important;min-height:44px!important;
}
body #app .task-sheet-chrome{grid-template-columns:44px minmax(0,1fr) 44px 44px!important}
body #app .task-sheet-chrome.has-qr-corner:has(>#lumo-scan-qr:not([hidden])){
 grid-template-columns:44px minmax(0,1fr) 44px 44px 44px!important;
}
/* QR is a fourth child in eligible signed-in onboarding headers. */
body #app .screen .onboarding-page>.topline.has-qr-corner:has(>#lumo-scan-qr:not([hidden])){
 grid-template-columns:44px minmax(0,1fr) 44px 44px;
}
body #app .edition-home.everyday-account-home .home-header-actions,
body #app .screen .hibiscus-header-utilities{gap:4px}
body #app .edition-home.everyday-account-home .everyday-budget-link,
body #app .edition-home.everyday-account-home :is(.everyday-gap,.everyday-pending){min-height:44px!important}
@media(max-height:620px){
 body #app .edition-home.everyday-account-home .everyday-add-money,
 body #app .edition-home.everyday-account-home .everyday-home-actions>button{min-height:44px!important}
}
@media(max-width:359px){
 /* 86px wordmark + 4×44px actions + 6px gaps + 8px outer gap = 276px. */
 body #app .edition-home.everyday-account-home .home-header-actions,
 body #app .screen .hibiscus-header-utilities{gap:2px!important}
 body #app .screen .onboarding-page>.topline.has-qr-corner{gap:4px}
}

/* Comparable labels/decisions get comparable type. True metadata stays quiet. */
body #app #view .screen .field>span,
body #app #view .gm-page .field>span{font-size:.875rem!important;line-height:1.4!important}
body #app #view .screen :is(.sh-consent,.sh-cancel-confirm p),
body #app #view .gm-page :is(.gm-note,.gm-mandate-choice p,.gm-mandate-preview p,.gm-mandate-summary p,.gm-mandate-rules li,.gm-role-summary>p,.gm-invitation-role>p,.gm-invitation-mandate>p){
 font-size:.875rem!important;line-height:1.5!important;
}
body #app #view .gm-page .gm-person-copy small{font-size:.75rem;line-height:1.4}
body #app #view .screen .sh-consent{min-height:44px}

/* Inline checkboxes are controls with adjacent captions, not flexible fields. */
body #app #view .screen label.inline:has(>input:is([type=checkbox],[type=radio])){
 display:flex;flex-direction:row;flex-wrap:nowrap;align-items:flex-start;
 gap:10px;min-height:44px;font-size:.875rem;line-height:1.5;cursor:pointer;
}
body #app #view .screen label.inline>input:is([type=checkbox],[type=radio]){
 flex:0 0 20px!important;width:20px!important;min-width:20px!important;max-width:20px!important;
 height:20px!important;min-height:20px!important;padding:0!important;margin:2px 0 0!important;
 accent-color:var(--ink);
}

/* Hibiscus fields need a distinguishable edge, without darkening card dividers.
   #927e98 is >3:1 against card, paper and sunken surfaces. Keep focus/errors. */
body.hibiscus-edition #app .screen :is(input,select,textarea):not([type=checkbox]):not([type=radio]):not([type=hidden]):not([type=range]):not([type=color]):not([type=file]):not(.amount-input):not(:disabled):not([aria-invalid=true]):not(:focus){
 border-color:#927e98!important;
}
body.hibiscus-edition #app .screen .phone-field>span{border-color:#927e98!important}
/* Selected people must remain identifiable before delegating approval. */
body.hibiscus-edition #app #view .gm-page .gm-contact.selected .gm-person-copy :is(strong,small){
 color:var(--onInk,#fff)!important;
}

/* Profile facts get the available value column instead of a narrow text strip. */
body.hibiscus-edition #app .screen-profile .account-flow>.soft>.summary-line{
 display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);align-items:start;gap:12px;
}
body.hibiscus-edition #app .screen-profile .account-flow>.soft>.summary-line>:is(span,strong){
 min-width:0;width:auto;max-width:none!important;
}
body.hibiscus-edition #app .screen-profile .account-flow>.soft>.summary-line>strong{
 text-align:right;overflow-wrap:anywhere;
}

/* Names can wrap in payment lists; the nowrap money rule must not reach them. */
body #app #view .chat-calendar-payments .row-copy strong{
 white-space:normal!important;overflow-wrap:anywhere;
}

/* Give savings its own full-width row, in both privacy states. This keeps the
   enlarged amount inside the card without shrinking its text or moving art. */
body #app .screen-home .edition-home.everyday-account-home .everyday-boxes-open{
 grid-template-rows:auto auto auto auto;gap:2px 11px;
}
body #app .screen-home .edition-home.everyday-account-home .everyday-boxes-copy{display:contents}
body #app .screen-home .edition-home.everyday-account-home .everyday-boxes-icon{grid-column:1;grid-row:1/span 2}
body #app .screen-home .edition-home.everyday-account-home .everyday-boxes-title{
 grid-column:2;grid-row:1;white-space:normal!important;overflow-wrap:normal;word-break:normal;
}
body #app .screen-home .edition-home.everyday-account-home .everyday-boxes-copy>small:not(.everyday-boxes-count){grid-column:2;grid-row:2;margin:0!important}
body #app .screen-home .edition-home.everyday-account-home .everyday-savings-amount{grid-column:1/-1;grid-row:3;margin:0!important}
body #app .screen-home .edition-home.everyday-account-home .everyday-boxes-count{grid-column:1/-1;grid-row:4;margin:0!important}
body #app .screen-home .edition-home.everyday-account-home .everyday-boxes-open>svg{grid-column:3;grid-row:1/span 2}

/* Hidden balances need the same intrinsic line reservation as shown balances.
   Neutral tabular glyphs wrap with the existing currency/whole/cents styles;
   no private number is duplicated in hidden markup or measured off-screen. */
body #app .screen-home .edition-home.everyday-account-home .everyday-primary-money>strong{
 display:grid!important;grid-template-columns:minmax(0,1fr);grid-template-areas:"amount";
}
body #app .screen-home .edition-home.everyday-account-home .everyday-primary-money>strong>:is([data-private-value],.product-money-reserve){
 grid-area:amount;min-width:0;max-width:100%;
}
body #app .screen-home .edition-home.everyday-account-home .everyday-primary-money>strong>[data-private-value]{justify-self:start}
body #app .screen-home .edition-home.everyday-account-home .product-money-reserve{
 visibility:hidden;pointer-events:none;font:inherit!important;line-height:inherit!important;
 letter-spacing:inherit;white-space:normal;overflow-wrap:anywhere;
}
body #app .screen-home .product-reserve-currency::before{content:"GH₵"}
body #app .screen-home .product-reserve-whole::before{content:"000"}
body #app .screen-home .product-money-reserve-wide .product-reserve-whole::before{content:"0,000,000"}
body #app .screen-home .product-money-reserve-huge .product-reserve-whole::before{content:"000,000,000,000"}
body #app .screen-home .product-reserve-cents::before{content:".00"}
body #app .screen-home .edition-home.everyday-account-home .experience-budget-basis{
 white-space:normal!important;overflow-wrap:normal;
}

/* Labels and amounts move to separate lines when their intrinsic sizes need
   the width. A long amount never crushes a label into a few pixels. */
body #app #view .balance-calculation>div{flex-wrap:wrap;gap:6px 12px}
body #app #view .balance-calculation dt{flex:1 1 9em;overflow-wrap:normal;word-break:normal}
body #app #view .balance-calculation dd{flex:0 1 auto;min-width:0;max-width:100%;margin-left:auto}
body.hibiscus-edition #app .screen-plan .budget-overview-context>span{flex-wrap:wrap;min-width:0;max-width:100%}
body.hibiscus-edition #app .screen-plan .budget-overview-context>span strong{max-width:100%;margin-left:auto!important}

/* Intrinsic em columns preserve two small cards at ordinary type sizes and
   form one readable column when the customer enlarges the text. */
body.hibiscus-edition #app .screen-more .you-options{
 grid-template-columns:repeat(auto-fit,minmax(min(100%,max(45%,8.5em)),1fr))!important;
}
body.hibiscus-edition #app .screen-more .you-options>button{
 min-width:0;max-width:100%;width:100%;
}
body.hibiscus-edition #app .screen-more .you-options>button :is(strong,small){min-width:0;max-width:100%;overflow-wrap:anywhere}

