 --mono-ink:#161616;--mono-paper:#fafafa;--mono-surface:#ffffff;--mono-soft:#f0f0f0;
 --mono-line:#e2e2e2;--mono-muted:#6c6c6c;--mono-acid:#d7ff3f;
 --ink:#161616;--muted:#6c6c6c;--paper:#fafafa;--white:#ffffff;--soft:#f0f0f0;--line:#e2e2e2;
 --green:#d7ff3f;--red:#161616;--green-ink:#161616;--green-soft:#f0f0f0;
