/* Source: mono-type-consistency.css | sha256:7575cd9fb9868285da6c3d0b97b05f857101d14e1363a7e3ebf096759baeea61 */
/* Monochrome type roles. One family, medium lead amounts and semibold records.
   Sizes, line heights, currency/decimal scaling and privacy sizing stay owned
   by their existing components. No financial or interaction authority. */
body.minna-edition{
 --mono-font-ui:'Manrope UI',sans-serif;
 --font-ui:var(--mono-font-ui);
 --font-interface:var(--mono-font-ui);
 --font-body:var(--mono-font-ui);
 --font-heading:var(--mono-font-ui);
}
body.minna-edition #app,
body.minna-edition #app .screen{
 font-family:var(--mono-font-ui);
 font-synthesis:none;
}
body.minna-edition #app :is(button,input,select,textarea){font-family:inherit}

/* Monetary roles use the same lining, equal-width digits. Security codes,
   masked card numbers, OTP cells, chart labels and ordinary prose retain
   their deliberate spacing and emphasis. The cedi fallback stays intact. */
body.minna-edition #app :is(
 [data-private-value],.balance-number,.money,.metric,.lumo-amount,
 .focus-amount,.balance-main,.amount-input,.payment-fact-amount,
 .payment-balance-number,.payment-fact-number,.everyday-savings-amount,
 .mono-context-amount,.plan-hub-amount,.budget-overview-item-amount,
 .budget-overview-edit-total>strong,.plan-dates-total>strong,
 .budget-review-totals dd,.budget-review-category dd,.outlook-daily-value,
 .outlook-conclusion>h1,.outlook-calculation dd,.saving-milestone-amount>strong,
 .focus-payment-title h1,.focus-story-total>strong,.ms-total,
 .ms-chart-values dd,.ms-breakdown dd,.ms-payment>strong,
 .daily-story-conclusion>strong,.daily-story-details dd,.daily-story-payment>strong,
 .receipt strong,.focus-receipt strong,.summary-line strong,.chat-calculation dd,
 .gm-amount,.gm-person-amount,.gm-trailing,.gm-summary dd,.gm-activity-row>strong,
 .cc-result-amount,.cpr-review .focus-payment-title h1,
 input[type=number],input[inputmode=decimal]
){font-variant-numeric:lining-nums tabular-nums}
body.minna-edition #app #view .mono-home .mono-context-amount::after{
 font-variant-numeric:lining-nums tabular-nums;
}

/* The lead figure is recognisably the same treatment from Home through
   planning, savings, payment review, authorisation and the final receipt. */
body.minna-edition #app #view :is(
 .mono-home .everyday-primary-money>strong,
 .plan-hub-amount,.budget-overview-edit-total>strong,.plan-dates-total>strong,
 .outlook-daily-value,.outlook-conclusion>h1,
 .screen-goals>.hero .balance-main,.screen-goal>.hero .balance-main,
 .saving-milestone-amount>strong,.gm-page .gm-amount,
 .screen-paymentReview .focus-payment-title h1,
 .screen-authorize .hero h1,.screen-txDetail .hero h1,
 .screen-requestDetail .hero h1,.screen-requestConfirm .hero h1,
 .payment-fact-amount,.amount-input,.ms-total,.daily-story-conclusion>strong,
 .cpr-review .focus-payment-title h1
){font-weight:500!important}

/* Dense records share a semibold figure, including the group facts that
   previously used an intermediate550 weight. */
body.minna-edition #app #view :is(
 .receipt strong,.focus-receipt strong,.summary-line strong,.chat-calculation dd,
 .gm-summary dd,.gm-person-amount,.gm-activity-row>strong,
 .ms-breakdown dd strong,.ms-payment>strong,.daily-story-details dd
){font-weight:600!important}

/* Supporting account balances keep the quieter medium weight used by Home. */
